<?php
if($_SERVER['REQUEST_METHOD']==='POST'){
 verifyCsrf();$action=$_POST['action']??'';
 if($action==='product'){$id=(int)($_POST['id']??0);$data=[trim($_POST['name']??''),trim($_POST['description']??''),trim($_POST['features']??''),(int)($_POST['sort_order']??0),isset($_POST['status'])?1:0];if($id)$db->execute('UPDATE products SET name=?,description=?,features=?,sort_order=?,status=? WHERE id=?',[...$data,$id]);else$db->execute('INSERT INTO products(name,description,features,sort_order,status)VALUES(?,?,?,?,?)',$data);}
 if($action==='variant'){$id=(int)($_POST['id']??0);$data=[(int)$_POST['product_id'],trim($_POST['name']??''),(float)$_POST['price'],$_POST['supplier_type']==='api'?'api':'manual',trim($_POST['provider_code']??''),(int)($_POST['sort_order']??0),isset($_POST['status'])?1:0];if($id)$db->execute('UPDATE variants SET product_id=?,name=?,price=?,supplier_type=?,provider_code=?,sort_order=?,status=? WHERE id=?',[...$data,$id]);else$db->execute('INSERT INTO variants(product_id,name,price,supplier_type,provider_code,sort_order,status)VALUES(?,?,?,?,?,?,?)',$data);}
 redirectAdmin('products','Đã lưu sản phẩm.');
}
$products=$db->fetchAll('SELECT * FROM products ORDER BY sort_order,id');$variants=$db->fetchAll('SELECT v.*,p.name product_name FROM variants v JOIN products p ON p.id=v.product_id ORDER BY p.sort_order,v.sort_order,v.id');
?>
<h1>Sản phẩm</h1><div class="card"><h3>Thêm sản phẩm</h3><form method="post"><input type="hidden" name="csrf" value="<?=e(csrfToken())?>"><input type="hidden" name="action" value="product"><input name="name" placeholder="Tên sản phẩm" required><textarea name="description" placeholder="Mô tả ngắn"></textarea><textarea name="features" placeholder="Mỗi tính năng một dòng"></textarea><input name="sort_order" type="number" value="0"><label><input type="checkbox" name="status" checked style="width:auto"> Hiển thị</label><br><button>Lưu sản phẩm</button></form></div>
<div class="card"><h3>Thêm gói</h3><form method="post"><input type="hidden" name="csrf" value="<?=e(csrfToken())?>"><input type="hidden" name="action" value="variant"><select name="product_id" required><?php foreach($products as $p):?><option value="<?=e($p['id'])?>"><?=e($p['name'])?></option><?php endforeach;?></select><input name="name" placeholder="Tên gói" required><input name="price" type="number" min="0" placeholder="Giá" required><select name="supplier_type"><option value="manual">Kho nhập tay</option><option value="api">API nhà cung cấp</option></select><input name="provider_code" placeholder="Mã gói API (nếu có)"><input name="sort_order" type="number" value="0"><label><input type="checkbox" name="status" checked style="width:auto"> Hiển thị</label><br><button>Lưu gói</button></form></div>
<div class="card"><table><thead><tr><th>Sản phẩm</th><th>Gói</th><th>Giá</th><th>Nguồn</th><th>Trạng thái</th></tr></thead><tbody><?php foreach($variants as $v):?><tr><td><?=e($v['product_name'])?></td><td><?=e($v['name'])?></td><td><?=e(Helpers::money($v['price']))?></td><td><?=e($v['supplier_type'])?></td><td><?=$v['status']?'Bật':'Tắt'?></td></tr><?php endforeach;?></tbody></table></div>
